/* TNM World Wrestling Report: FMW (Frontier Martial-Arts Wrestling).
   Everything the site shows for this promotion lives in this file. Added 2026-11-14. */

P.fmw = {"short": "FMW", "nav": "FMW", "name": "Frontier Martial-Arts Wrestling", "home": "Tokyo", "c": "var(--fmw)", "status": "Night 2 drew 2,654 in Konan 7/20 for $26,540, 1,100 more than Sagamihara on a five-match card. Tarzan Goto's chair hit Mr. Pogo and Onita rolled Goto up. The Sheik made Sabu submit to the camel clutch and threw fire at his nephew. Big Titan's chokeslam on Sambo Asako was the match of the tour (***1/4). Kochi 7/22 is next.", "stat": ["$15,580", "gate, night 1"], "titles": [["FMW titles", "To establish", "No championships are set up in the game yet."]], "factions": [["Onita's FMW", "Atsushi Onita founded the promotion in 1989 and is still its ace. Garbage wrestling, barbed wire and death matches."], ["The Soviet team", "Grigory Verichev, Boris Gogichashvili, Koba Kurtanidze and Svetlana Goundarenko."], ["The imports", "The Sheik, Leon Spinks, Kevin Sullivan, Sabu, Big Titan, Horace Boulder, Mark Starr, Kerry Brown, Jimmy Backlund, The Gladiator, and Debbie Combs, Reggie Bennett and Debbie Malenko for the women."], ["The women's division", "Megumi Kudo, Combat Toyoda, Eriko Tsuchiya, Yoshika Maedomari, Keiko Iwami, Kumiko Matsuda, Yuki Morimatsu, Rie Nakamura and Yukie Nabeno, plus the imports."]], "stories": [["Goto's Chair Hits Pogo", "Tarzan Goto swung a chair at Atsushi Onita in the Konan main event 7/20, hit his own partner Mr. Pogo instead, and Onita rolled him up. One night after Pogo said Goto chose New Japan, the heel side has two leaders who just hurt each other."], ["The Sheik Turns on Sabu", "One night after they teamed in Sagamihara, the Sheik sided with Horace Boulder, made Sabu submit to the camel clutch in Konan 7/20, and threw fire at him. Ricky Fuji dragged Sabu out."], ["Titan Over Asako", "Big Titan chokeslammed Sambo Asako in a no countout, no DQ match in Konan 7/20, ***1/4, the best FMW match of the tour."], ["Frontier Joins the World", "FMW opened its Summer tour in Sagamihara on 7/19 with 1,558 fans. Onita promised fights the others won't put on TV; Pogo, Titan and Boulder answered from the stage and beat him, Asako and Fuji in an 18:52 street fight (**3/4), with Fuji powerbombed through a table."], ["Sullivan Lands in Japan", "Kevin Sullivan quit WCW on July 8. In his FMW debut he tombstoned Yukihide Ueno, tombstoned Ricky Fuji on the floor, then shook Mr. Pogo's hand after the main event and told Onita he wants him next."], ["Goto vs. Pogo", "Tarzan Goto worked New Japan's Sapporo TV taping 7/19 and appeared on tape only. Pogo told Sagamihara that Goto chose New Japan, and that Sullivan came from America to stand with him. Goto and Pogo team against Onita and Verichev in Konan 7/20."], ["The Shooter Shocks Verichev", "Grigory Verichev came in billed as the Soviet nobody could beat. The Shooter made him tap to an armbar in 6:11 in Sagamihara. Verichev partners Onita in Konan."], ["Ezaki's First Win", "Rookie Eiji Ezaki made Akihito Ichihara submit to a Boston crab, Ichihara's own finisher, in the Sagamihara opener."], ["Shared with New Japan", "Tarzan Goto and Masashi Aoyagi are on NJPW's Summer Crush tour through July 30."]], "desk": ["Konan 7/20: 2,654 at $10 = $26,540, merch $1,327 (50 cents a head). Card *. MOTN: Titan vs. Asako, ***1/4. Five matches, 16 wrestlers.", "Goto works NJPW Sendai 7/22 while FMW runs Kochi (Pogo, Titan & Boulder vs. Onita, Asako & Fuji, No-DQ bunkhouse).", "Sagamihara City General Gym: about 1,600 seats in the stands plus floor. Venues and capacities for the other stops: To establish.", "Payroll for Sagamihara: $9,950 for 28 workers, 64% of the gate. Well over the 35% target at a $10 ticket.", "Tarzan Goto keeps all his New Japan dates (7/19, 7/22, 7/29, 7/30) and works FMW at Konan 7/20 only, so Mr. Pogo carries the heel side the other nights.", "Masashi Aoyagi is in New Japan's Sendai show 7/22; free 7/19 and 7/20.", "Kevin Sullivan (50 cards) is also talking to CMLL about Gran Prix dates. Check before booking him past July.", "Not yet checked against other promotions' dates: Sabu, Mark Starr, Jimmy Backlund, Debbie Combs, Debbie Malenko, Reggie Bennett, Kerry Brown. Check before each card.", "Short deals: Debbie Combs, Debbie Malenko, Reggie Bennett (20 cards); Katsuji Ueda, Yuki Morimatsu (24); Megumi Kudo, Kumiko Matsuda, The Shooter (22).", "Onita vs. Pogo blow-off: stipulation, date and site To establish.", "Leon Spinks needs a big-name opponent after the tour: To establish.", "Which titles does FMW open with, and who's the first champion?", "Only the 39 under contract work FMW shows for now. Pay rates are a draft until the office signs off.", "Official FMW site is up, with Sagamihara 7/19 as its first show page."], "departures": [], "roster": [["Atsushi Onita", "Wrestler and promoter, paid as both; 50 cards left"], ["The Sheik", "Special attraction import; 50 cards left"], ["Tarzan Goto", "Also NJPW (Summer Crush through 7/30); 50 cards left"], ["Mr. Pogo", "52 cards left"], ["Leon Spinks", "Celebrity import, former boxing champion; 39 cards left"], ["Grigory Verichev", "Soviet team; 50 cards left"], ["Sabu", "50 cards left"], ["Kevin Sullivan", "Quit WCW 7/8; 50 cards left"], ["Mitsuhiro Matsunaga", "\"Mr. Danger\"; 45 cards left"], ["Megumi Kudo", "Women's division; 22 cards left"], ["Combat Toyoda", "Women's division; 40 cards left"], ["Svetlana Goundarenko", "Women's division, Soviet team; 39 cards left"], ["Big Titan", "50 cards left"], ["Ricky Fuji", "50 cards left"], ["Horace Boulder", "\"The Predator\"; 50 cards left"], ["Debbie Combs", "Women's division, import; 20 cards left"], ["Reggie Bennett", "Women's division, import; 20 cards left"], ["Jimmy Backlund", "50 cards left"], ["Sambo Asako", "30 cards left"], ["Katsuji Ueda", "24 cards left"], ["Kerry Brown", "Has worked the USWA (Louisville 7/13); 50 cards left"], ["Debbie Malenko", "Women's division, import; 20 cards left"], ["Masashi Aoyagi", "Also NJPW (Summer Crush through 7/30); 50 cards left"], ["Boris Gogichashvili", "Soviet team; 30 cards left"], ["Koba Kurtanidze", "Soviet team; 32 cards left"], ["Mark Starr", "50 cards left"], ["The Gladiator", "Tags with Big Titan; 30 cards left"], ["Eriko Tsuchiya", "Women's division; 30 cards left"], ["Yoshika Maedomari", "Women's division; 30 cards left"], ["The Shooter", "22 cards left"], ["Masashi Honda", "30 cards left"], ["Eiji Ezaki", "Rookie; 50 cards left"], ["Yukihide Ueno", "Rookie; 50 cards left"], ["Akihito Ichihara", "Rookie; 30 cards left"], ["Keiko Iwami", "Women's division; 40 cards left"], ["Kumiko Matsuda", "Women's division; 22 cards left"], ["Yuki Morimatsu", "Women's division; 24 cards left"], ["Rie Nakamura", "Women's division; 50 cards left"], ["Yukie Nabeno", "Women's division; 50 cards left"]], "asOf": "1991-07-20"};

E.push(...[{"d": "1991-07-19", "p": "fmw", "city": "Sagamihara, Kanagawa", "venue": "Sagamihara City General Gym", "type": "Summer tour, Night 1", "ran": 1, "gate": "1,558 · $15,580", "rate": "1/4*", "m": [["Eiji Ezaki vs. Akihito Ichihara", "Ezaki (Boston crab), 10:00", "-**3/4"], ["Rie Nakamura vs. Yukie Nabeno", "Nakamura (bridging back suplex), 8:20", "-**3/4"], ["Different-style fight: Grigory Verichev vs. The Shooter", "The Shooter (armbar), 6:11", "-***"], ["Gogichashvili & Kurtanidze vs. Mark Starr & Jimmy Backlund", "Gogichashvili pins Backlund (atomic throw), 9:40", "1/4*"], ["Combat Toyoda & Megumi Kudo vs. Svetlana Goundarenko & Debbie Combs", "Toyoda pins Combs (powerbomb), 11:19", "*"], ["Boxer vs. wrestler: Leon Spinks vs. Masashi Honda", "Spinks (uppercut), 5:52", "-***3/4"], ["No-DQ: Kevin Sullivan vs. Yukihide Ueno", "Sullivan (tombstone), 7:13. Tombstones Fuji on the floor", "1/4*"], ["The Sheik & Sabu vs. Mitsuhiro Matsunaga & Katsuji Ueda", "Ueda passes out in Sheik's camel clutch, 10:37. Fireball after", "1/2*"], ["Falls-count-anywhere street fight: Mr. Pogo, Big Titan & Horace Boulder vs. Atsushi Onita, Sambo Asako & Ricky Fuji", "Pogo's team; Fuji powerbombed through a table, 18:52. Match of the night", "**3/4"]], "link": "FMW_SAGA", "n": ["Opening promo: Onita, \"Frontier Joins the World.\" Pogo, Titan & Boulder answer from the stage.", "Pretaped video: Tarzan Goto from the bus (at NJPW Sapporo TV tonight).", "Closing angle: Kevin Sullivan shakes Mr. Pogo's hand and tells Onita he wants him next.", "1,558 (about 1,600 seats in the stands) at $10 for $15,580. Merchandise $779 (50 cents a head)."], "reads": [["Observer report", "fmw-observer-sagamihara-0719"], ["From the Road: Eiji Ezaki", "fmw-diary-ezaki-0719"]]}, {"d": "1991-07-20", "p": "fmw", "city": "Konan, Aichi", "venue": "Aichi Konan Citizen Gym", "type": "Summer tour, Night 2", "ran": 1, "rate": "*", "gate": "2,654 · $26,540", "m": [["Masashi Honda vs. Yukihide Ueno", "Honda (bodytrap cradle), 7:44", "-***"], ["Eriko Tsuchiya & Rie Nakamura vs. Keiko Iwami & Yukie Nabeno", "Tsuchiya pins Nabeno (asai leg lariat), 11:03", "-***1/4"], ["The Sheik & Horace Boulder vs. Sabu & Ricky Fuji", "Sheik makes Sabu submit (camel clutch), 11:58. Sheik throws fire at Sabu after", "3/4*"], ["No countout, no DQ: Big Titan vs. Sambo Asako", "Titan (chokeslam), 15:38", "***1/4"], ["Main: Atsushi Onita & Grigory Verichev vs. Tarzan Goto & Mr. Pogo", "Onita rolls up Goto, 17:53, after Goto's chair hits Pogo", "*"]], "n": ["2,654 at $10 = $26,540, plus $1,327 merchandise (50 cents a head).", "Change from plan: Sheik & Boulder won by submission (booked: Sabu & Fuji by DQ for the fire).", "No injuries."], "reads": [["Goto's Chair, Pogo's Head, Onita's Win", "fmw-goto-chair-pogo-0720"], ["Observer report", "fmw-observer-konan-0720"], ["From the Road: Sabu", "fmw-diary-sabu-0720"]]}, {"d": "1991-07-22", "p": "fmw", "city": "Kochi, Kochi", "venue": "Kochi Prefectural Gym", "type": "Summer tour", "gate": "2,215", "m": [["Eiji Ezaki def. Akihito Ichihara (diving crossbody, 8:10)", "", ""], ["Women's #1 Contender: Megumi Kudo def. Yoshika Maedomari (Kudo Driver, 11:32). Earns the WWA Women's Title shot", "", ""], ["Martial Arts: Katsuji Ueda def. Koba Kurtanidze (spinning back kick KO, Round 2, 1:48)", "", ""], ["Sabu def. Mitsuhiro Matsunaga (moonsault onto a chair, 13:45)", "", ""], ["No-DQ Bunkhouse Brawl: Mr. Pogo, Big Titan & Horace Boulder def. Atsushi Onita, Sambo Asako & Ricky Fuji (spike piledriver on Asako onto chairs, 19:12)", "", ""]]}, {"d": "1991-07-26", "p": "fmw", "city": "Tokuyama, Yamaguchi", "venue": "Yamaguchi Tokuyama City Gym", "type": "Summer tour", "gate": "2,012", "m": [["Yukihide Ueno def. Masashi Honda (Northern Lights suplex, 8:55)", "", ""], ["Women's Tag: Yuki Morimatsu & Yukie Nabeno def. Rie Nakamura & Eriko Tsuchiya (German suplex on Tsuchiya, 10:40)", "", ""], ["The Sheik def. Boris Gogichashvili (camel clutch, 5:15)", "", ""], ["WWA Women's Title: Combat Toyoda (c) def. Megumi Kudo (diving splash, 16:20)", "", ""], ["Tarzan Goto & Mr. Pogo def. Atsushi Onita & Sabu (running powerbomb on Sabu, 17:48). Post-match strap whipping on Onita", "", ""]]}, {"d": "1991-07-27", "p": "fmw", "city": "Himeji, Hyogo", "venue": "Hyogo Himeji City Welfare Hall", "type": "Summer tour", "gate": "1,952", "m": [["Akihito Ichihara def. Eiji Ezaki (roll-up, 7:50)", "", ""], ["Women's: Eriko Tsuchiya def. Keiko Iwami (lariat, 9:15). Sets up the next Toyoda challenger", "", ""], ["Martial Arts Tag: Grigory Verichev & Katsuji Ueda def. Leon Spinks & Koba Kurtanidze (Kimura lock on Kurtanidze, 9:30)", "", ""], ["Big Titan & The Gladiator def. Sambo Asako & Ricky Fuji (big boot on Fuji, 13:05)", "", ""], ["Grudge Match: Atsushi Onita def. Mr. Pogo (Thunder Fire Powerbomb, 15:40). Goto challenges Onita to a barbed-wire test", "", ""]]}, {"d": "1991-07-29", "p": "fmw", "city": "Settsu, Osaka", "venue": "JR Settsu-Tonda Station Pachinko Diana parking lot, special ring", "type": "Summer tour", "gate": "1,752", "m": [["Eiji Ezaki & Masashi Honda def. Akihito Ichihara & Yukihide Ueno (moonsault on Ueno, 10:12)", "", ""], ["Women's Tag: Megumi Kudo & Yukie Nabeno def. Combat Toyoda & Eriko Tsuchiya (DQ, Toyoda & Tsuchiya attack the referee, 12:44)", "", ""], ["Sabu def. Boris Gogichashvili (Triple Jump Moonsault, 9:58)", "", ""], ["Mitsuhiro Matsunaga def. Sambo Asako (running lariat, 11:20)", "", ""], ["Street Fight Tag: Mr. Pogo & Horace Boulder def. Atsushi Onita & Ricky Fuji (barbed-wire kendo stick shot on Onita, 14:55). Fuji demands a solo deathmatch", "", ""]]}, {"d": "1991-07-30", "p": "fmw", "city": "Haibara, Nara", "venue": "Nara Prefectural Hagiwara Gym", "type": "Summer tour", "gate": "2,155", "m": [["Martial Arts: Katsuji Ueda def. The Shooter (TKO, Round 2, 2:55)", "", ""], ["Women's Tag: Yoshika Maedomari & Eriko Tsuchiya def. Megumi Kudo & Kumiko Matsuda (brainbuster on Matsuda, 13:10)", "", ""], ["Big Titan & The Gladiator def. Grigory Verichev & Eiji Ezaki (chokeslam on Ezaki, 11:45)", "", ""], ["Atsushi Onita & Sabu def. Mitsuhiro Matsunaga & The Sheik (Thunder Fire Powerbomb on the Sheik, 14:20)", "", ""], ["No Ropes Barbed Wire Street Fight Death Match: Mr. Pogo def. Ricky Fuji (powerbomb into a barbed-wire board, 16:08). Fuji stretchered out", "", ""]]}, {"d": "1991-07-31", "p": "fmw", "city": "Fukui, Fukui", "venue": "Fukui City Gym", "type": "Summer tour", "gate": "1,624", "m": [["Eiji Ezaki def. Mark Starr (bridging German suplex, 9:40)", "", ""], ["Martial Arts Tournament Qualifier: Grigory Verichev def. Katsuji Ueda (cross armbreaker, Round 4, 1:12)", "", ""], ["WWA Women's Title: Combat Toyoda (c) vs. Eriko Tsuchiya (double count-out, 15:00)", "", ""], ["Big Titan & The Gladiator def. Sambo Asako & Sabu (sit-out powerbomb on Asako, 14:15)", "", ""], ["Barbed Wire Board Tornado Tag Street Fight: Atsushi Onita & Ricky Fuji def. Tarzan Goto & Mr. Pogo (Thunder Fire Powerbomb on Pogo through a barbed-wire board, 21:18)", "", ""]]}]);

Object.assign(ARTICLES, {"fmw-observer-sagamihara-0719": {"p": "fmw", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-19", "region": "Japan Report", "kicker": "FMW · Sagamihara · 7/19", "title": "Observer: Sagamihara", "dek": "FMW nearly fills the building at $10 a head, The Shooter taps Verichev, a rookie wins the opener, and Kevin Sullivan shakes Pogo's hand.", "factTitle": "Match observations", "facts": [["Show", "Sagamihara, 7/19"], ["Venue", "Sagamihara City General Gym"], ["Attendance", "1,558"], ["Gate", "$15,580"], ["Merch", "$779"], ["Card", "1/4*"], ["Match of the night", "Pogo, Titan & Boulder d. Onita, Asako & Fuji, **3/4"]], "body": [["p", "FMW's first night on the world stage drew 1,558 into a gym with about 1,600 seats in the stands, so the place was close to full. The trouble is the ticket. At a $10 average the house came to $15,580, plus $779 in merchandise at 50 cents a head. There were 28 wrestlers on the card, including The Sheik, Leon Spinks, Kevin Sullivan and three Soviets, and the word is the night's payroll ran right around $10,000. That's close to two-thirds of the gate before the building, the ring truck and the hotels. Onita can fill a room. Whether he can make money filling it at these prices is another question."], ["p", "The card rated 1/4*, and that's with four matches below zero. The only thing that worked was the main event, and it worked because it was what FMW actually is: Onita bleeding inside five minutes, Ricky Fuji taking a beating for 19 minutes, the brawl going into the seats and a table at the end. It rated **3/4, the match of the night by more than two full stars."], ["p", "The different-style fights are the problem. Leon Spinks over Masashi Honda was -***3/4, the worst match of the night. It was five minutes of a former heavyweight boxing champion and a young wrestler who didn't know what to do with each other until the uppercut landed. The Shooter vs. Grigory Verichev came in at -***. The mixed-style fight is the idea Onita built this company on, but neither match looked like a fight or like wrestling, and the crowd sat on its hands for both."], ["p", "The result of the night was in that second one. Verichev came in billed as the Soviet nobody could beat, and The Shooter tapped him with an armbar in 6:11. People around the Soviet camp said Verichev had been in Japan only a few days and wasn't over the trip, and the Shooter caught him rolling through on the mat. Whatever the reason, it's done. Verichev teams with Onita against Goto and Pogo in Konan tomorrow with a loss already on his record, and The Shooter, on a short deal, suddenly has a name."], ["p", "The other surprise came in the opener. Rookie Eiji Ezaki made Akihito Ichihara submit to a Boston crab, Ichihara's own finisher, at 10:00. The match was -**3/4, which is what you get from two rookies, but Ezaki getting a submission win on night one says somebody in the office sees something. He faces Masashi Honda in Konan."], ["p", "Kevin Sullivan's first night in Japan was the best news on the show. He beat Yukihide Ueno with a tombstone in a no-DQ match (1/4*), dropped Fuji with another one on the floor when Fuji came in, and then walked out after the main event and shook Mr. Pogo's hand. Pogo's line about Goto choosing New Japan was the sharpest thing anyone said all night. Goto was in Sapporo working New Japan's TV taping and appeared only on a tape from the bus. The Pogo and Sullivan pairing puts a question mark over Goto before he even gets to Konan. Sullivan walked out of WCW on July 8, and there's still talk of CMLL wanting him for dates later in the summer."], ["p", "The Sheik and Sabu beat Matsunaga and Katsuji Ueda when Ueda passed out in the camel clutch at 10:37 (1/2*). Sheik threw fire at Matsunaga after the bell. Sheik is 65 and can't go, so what the match amounts to is the fireball and Sabu's flying around it. Matsunaga vs. Sabu is the program, and it's the one on this undercard with a future."], ["p", "The women got two matches. Combat Toyoda and Megumi Kudo beat Svetlana Goundarenko and Debbie Combs at * when Toyoda powerbombed Combs, and Rie Nakamura beat Yukie Nabeno with a bridging back suplex (-**3/4). Svetlana is a monster, and the right move is to keep her away from a pinfall for as long as possible. Combs is on a short deal."], ["p", "Gogichashvili and Kurtanidze beat Mark Starr and Jimmy Backlund at 1/4* when Gogichashvili pinned Backlund with an atomic throw."], ["h", "Results"], ["p", "1. Eiji Ezaki beat Akihito Ichihara by submission, Boston crab, 10:00. -**3/4"], ["p", "2. Rie Nakamura pinned Yukie Nabeno with a bridging back suplex, 8:20. -**3/4"], ["p", "3. Different-style fight: The Shooter beat Grigory Verichev by submission, armbar, 6:11. -***"], ["p", "4. Boris Gogichashvili & Koba Kurtanidze beat Mark Starr & Jimmy Backlund in 9:40 when Gogichashvili pinned Backlund with an atomic throw. 1/4*"], ["p", "5. Combat Toyoda & Megumi Kudo beat Svetlana Goundarenko & Debbie Combs in 11:19 when Toyoda pinned Combs with a powerbomb. *"], ["p", "6. Boxer vs. wrestler: Leon Spinks pinned Masashi Honda with an uppercut, 5:52. -***3/4"], ["p", "7. No-DQ: Kevin Sullivan pinned Yukihide Ueno with a tombstone piledriver, 7:13. Sullivan tombstoned Ricky Fuji on the floor. 1/4*"], ["p", "8. The Sheik & Sabu beat Mitsuhiro Matsunaga & Katsuji Ueda in 10:37 when Ueda passed out in Sheik's camel clutch. Fireball after. 1/2*"], ["p", "9. Falls-count-anywhere street fight: Mr. Pogo, Big Titan & Horace Boulder beat Atsushi Onita, Sambo Asako & Ricky Fuji in 18:52 when Fuji was powerbombed through a table and pinned. Match of the night. **3/4"], ["p", "Segments: Onita's opening promo, with Pogo's crew on the stage; Goto's taped message from the bus; Sullivan shakes Pogo's hand to close the show."], ["p", "Overall card: 1/4*"], ["p", "Next is Konan on 7/20, Onita & Verichev vs. Goto & Pogo, the only FMW night Goto works this week. Watch whether Pogo and Goto are still on the same page by the end of it."]]}, "fmw-diary-ezaki-0719": {"p": "fmw", "series": "diary", "by": "Eiji Ezaki", "date": "1991-07-19", "place": "The tour bus, Sagamihara", "kicker": "From the Road · Sagamihara, 7/19", "title": "Building the Ring", "dek": "Eiji Ezaki on putting up the ring, beating Ichihara with his own hold, and watching the Sheik's fire from the curtain.", "factTitle": "The Night", "facts": [["Show", "FMW Summer tour, Night 1"], ["Match", "Ezaki d. Akihito Ichihara"], ["Finish", "Boston crab, 10:00"], ["Rating", "-**3/4"]], "body": [["p", "We were at the gym at noon to put up the ring. Ueno, Ichihara and me, plus two of the boys from the office. It took three hours because the truck came late and Onita-san wanted the ring posts tight. In FMW the rookies build the ring, and then the rookies wrestle first."], ["p", "I was in the opener against Ichihara. Everyone knows his Boston crab. He put me in it in the dojo a hundred times, and I tapped a hundred times. Tonight he worked my back for ten minutes and I kept going to the ropes and coming off the top, because that is what I can do. When he turned me over for the crab again, I don't know what happened. I kicked, he fell, and I had his legs. I sat down on it. He tapped. I couldn't believe it, and I don't think he could either."], ["p", "In the back, Ichihara would not look at me. Later he came over and hit me on the chest and said, \"Next time.\" He means it."], ["p", "Then I watched the rest from the curtain. The Soviet, Verichev, lost to The Shooter, and the Russians were very quiet in the dressing room. Kurtanidze said something to him in Russian and Verichev just sat with his arm in ice. Leon Spinks knocked Honda down with one punch. Honda came back and said he never saw it."], ["p", "The Sheik threw fire. I have heard about it since I was a boy, but I had never seen it from ten meters away. You feel the heat on your face at the curtain."], ["p", "The main event was crazy. Onita-san was bleeding all over, and Fuji went through the table right in front of the front row. After that the American, Sullivan, went out and shook Pogo's hand. None of us knew what he was going to do. When the four of them came back through the curtain, Pogo was laughing."], ["p", "Then we took the ring down. Fuji helped even after the table, holding his back. Onita-san stood in the middle of the gym and watched everybody work, and when we were done he told me the crab was a good finish. That's the first thing he has ever said to me about a match."], ["p", "Tomorrow is Konan. I have Honda. On the bus now, and my back hurts from both the crab and the ring."]]}, "fmw-frontier-joins": {"p": "fmw", "news": 1, "by": "Newsletter staff", "date": "1991-07-16", "region": "Japan Report", "kicker": "FMW · Newcomer", "title": "Frontier Joins the World", "dek": "Atsushi Onita's FMW is the tenth promotion on the board, with Mr. Pogo, Tarzan Goto, Sabu, a Soviet team and a full women's division.", "body": [["p", "Frontier Martial-Arts Wrestling is the newest promotion in the TNM world. Atsushi Onita started FMW in 1989 with a few thousand dollars and a lot of barbed wire, and two years later it has 39 wrestlers under contract."], ["p", "Onita is the ace. Mr. Pogo and Tarzan Goto are the top heels, and the imports include The Sheik, Leon Spinks and Sabu. Kevin Sullivan, who walked out of WCW on July 8, is on the roster too."], ["h", "More than one division"], ["p", "FMW also brings a Soviet team led by Grigory Verichev, and a women's division headed by Megumi Kudo and Combat Toyoda, with Debbie Combs, Reggie Bennett and Debbie Malenko coming in from America."], ["p", "Tarzan Goto and Masashi Aoyagi are also working New Japan's Summer Crush tour through July 30, so FMW will have to work around those dates. The July schedule is still being set."]], "factTitle": "FMW at a glance", "facts": [["Founded", "1989, by Atsushi Onita"], ["Home", "Tokyo"], ["Roster", "39"], ["Shared", "Tarzan Goto, Masashi Aoyagi (NJPW)"], ["Pay", "Per show (draft)"]]}});

